// P-PSS-2048 covers R-SIG-LEN, R-EMBITS, R-I2OSP, R-SP1, R-MHASH, R-MPRIME, R-H, R-PS, R-DB, R-DBMASK, R-TOPBITS, R-EM, R-MGF-C, R-MGF-T, R-MGF-OUT — under a 2048-bit key, a signature is 256 octets and its encoded message is maskedDB, H and 0xbc, with H the hash of M' and DB the zero octets, 0x01 and the salt under the MGF1 mask of H with its top bit cleared
// samples: 24
forall (msg: u8[] /* 0..100 */, salt: u8[] /* 0..222 */) =>
  { const key = unwrap(rsaParsePrivateKey([30 82 04 a4 02 01 00 02 82 01 01 00 b1 b4 17 b2 31 66 55 67 d0 a5 11 19 58 b5 6e d8 6b b5 09 3d 49 42 05 cc 28 80 73 56 fb b2 07 9e ee 2f 12 9a 39 6a 92 a0 c7 ac 64 1f b6 73 1e 36 72 be ba 2e 80 ea 46 f2 ab 85 48 ee a0 94 4b 6f 4d 30 30 99 d7 48 58 5f 38 ed 0d 0b ed 31 a1 95 e7 fa de 69 9c 27 28 d8 77 ec 30 31 37 00 40 fc f4 ea 9b 73 eb c0 a7 02 63 ee 54 9e e6 10 a6 ee 96 8d 8f e1 a8 4b 9c 39 9b b8 68 7c e9 40 de 0c 30 3a 47 6e 93 65 56 6c ea d1 1a 5c b1 d5 04 66 ab 68 e8 39 7a da 38 55 2a 84 fa cb 99 ed a0 af f3 79 ee 96 83 9d 96 9a 6f 08 87 53 e4 a1 c5 3b cd e5 27 3b 76 6d 09 fb 51 6d cd 64 f5 a4 d2 1b ac ce eb 64 6d fb 65 8d e3 dd 3b d5 8e 06 35 34 5b da 3a 03 f9 c2 f8 71 03 c3 d5 82 63 19 8b 2a 90 9d 5a 9c 9b 7d b3 69 a5 b5 5e 45 97 b5 8b 86 e5 55 da 63 9c c8 ac 56 8b a9 64 86 88 d6 4a 6d 02 03 01 00 01 02 82 01 00 39 77 55 60 65 34 44 33 35 d8 63 8e b0 4e c0 01 51 d7 72 1c f5 17 5a 3b 9a ef 6b 1d 3a 78 e8 98 ff 4a 8e b7 fc 10 58 49 91 38 d1 0a 26 5c d4 ec e3 af 85 12 eb d2 97 4d fb a4 b7 20 a0 22 44 c0 c2 13 ee eb 99 20 86 9f 88 8f b4 33 e2 a9 35 a9 7e 22 f5 10 ef 14 04 d3 f7 f8 13 df 9e 7b 41 08 ec 84 ff ef 7d 52 48 4f f0 14 0f 1e 71 a4 f9 ee d7 16 01 6d 06 99 28 f4 c2 44 60 d9 e0 2e 7f 7f a4 0f 7d d4 d0 5c cb 21 d9 d0 ea 47 da 43 56 e1 4d 2b 4c 64 d0 15 b9 12 f9 cd 91 20 b2 f8 8d 2e b5 99 73 70 19 c7 a1 c0 7b c5 9e 14 68 5b 67 20 e4 0a ca 6e 00 a1 f8 1d 13 cd d9 4a 03 3e 4a 92 ad 30 f0 be e0 69 97 1b 7f d0 5c 19 f7 f6 90 ef 66 14 b8 f7 e1 67 16 59 d3 ae 4f 74 c3 e6 94 c3 2a 8c 51 28 09 33 6c 8c 53 39 2b 4f 56 dd e4 e4 c0 98 89 7f 86 8b 1d 75 01 4e fe 05 47 83 28 bb 02 81 81 00 e8 df fd 01 d9 80 db 9f a5 ae 08 73 77 eb 9d 36 46 08 bf fc 7a 2a f3 15 7b ff b7 53 0f 4f 4d c7 39 8c c2 fc 60 94 bc 97 35 45 df c6 d2 66 84 57 d2 b2 1b 20 27 9e b1 f5 9e 05 88 11 0d 1e 2b 90 a4 49 44 24 80 58 34 ee bd 5a b7 03 c6 3d ec 37 a2 95 4b f5 87 96 df 6a b4 a2 a8 d5 44 2d ee 97 64 a2 a9 41 b6 62 84 a0 19 09 a2 2e 76 97 fb 4d 3b 7c 55 f