6(concat(h, [00 00 00 03])), concat(sha256(concat(h, [00 00 00 04])), concat(sha256(concat(h, [00 00 00 05])), sha256(concat(h, [00 00 00 06])))))))).slice(0, 223); const db = xor(em.slice(0, 223), mask); return sig.length === 256 && em.slice(255, 256) === [bc] && bitAnd(em.slice(0, 1), [80]) === [00] && h === sha256(concat(zeros(8), concat(sha256(msg), salt))) && concat(bitAnd(db.slice(0, 1), [7f]), db.slice(1, 223)) === concat(zeros(222 - salt.length), concat([01], salt)); }

// P-PSS-2049 covers R-SIG-LEN, R-EMBITS, R-EMLEN, R-I2OSP, R-SP1, R-MHASH, R-MPRIME, R-H, R-PS, R-DB, R-DBMASK, R-TOPBITS, R-EM, R-MGF-C, R-MGF-T, R-MGF-OUT — under a 2049-bit key, a signature is 257 octets and its encoded message is 256, one less than k, with no bit of maskedDB cleared
// samples: 24
forall (msg: u8[] /* 0..100 */, salt: u8[] /* 0..222 */) =>
  { const key = unwrap(rsaParsePrivateKey([30 82 04 a5 02 01 00 02 82 01 01 01 50 26 d2 84 11 1f a2 d4 30 00 51 76 f8 09 e7 fc 90 75 15 8b 5b d5 96 10 a1 7b f5 2e d3 55 0d 9e e1 3e a0 97 ee 7c 8d 51 52 b5 e5 ba 6b 07 5a 24 6d 3a 1c 4a f6 bf ce b8 87 83 94 cf 3a d9 d2 15 bb 5c 2c 5c 9b 10 73 d4 5a 62 47 b0 8c 1c 88 b9 fb 3f b3 41 35 b4 96 03 48 d9 08 b8 b9 2b 72 bd 66 22 c1 ec e4 93 87 c7 84 cd a8 be b8 9b b1 58 6a fa c5 66 58 f1 34 57 55 f9 01 c7 32 9d 44 62 21 bb 82 71 7b d5 8b c7 f3 32 7c e6 9c c6 a6 b7 46 be 39 2e 74 50 d8 ae a6 28 73 f9 0a 6b 08 97 5d 77 06 d8 9d 79 2e d5 4b 4f 1b 73 fb 67 11 78 c7 eb d5 c3 8a 56 36 90 94 7b d5 e5 fc fa b7 82 bf 0c 24 cb 6a 30 73 4a c3 3c 7a b6 84 ac 51 f4 0f 53 8d f7 81 d8 ab fc 90 0c 05 03 0d 00 87 d2 44 7b cc d4 bf 58 3a 98 89 19 cc 2e dd ec c3 d8 0c bc cf 2b f2 32 8f 08 28 5b 00 e6 83 8f 85 83 02 03 01 00 01 02 82 01 01 01 3d 85 be 5a 73 96 4f 87 60 e4 1c 0f 65 92 6d e8 bb 47 6d 97 5a a2 b1 02 7a 97 0d 6d 32 c0 67 82 49 3f 90 10 93 7c 61 3c 8d 05 36 bf d5 33 77 a9 6a e7 76 2c 35 51 ce e1 ad 57 d4 2b bf 6a 5b 30 9d ef 1e 14 47 80 cd f8 ab 7b a4 3e 16 cb 29 37 8c 25 8a 9c 31 2f a8 77 e7 ca e2 9b 22 85 f0 f7 08 d0 12 20 43 75 3b cf 72 19 95 a8 b9 d6 8f 39 76 ab f3 e4 8e 65 20 cc d2 6f c8 87 31 bf 2e 03 dd 04 bc 4d 4d 1a 98 df e1 c5 b3 cb 5b f4 86 75 c9 cd dd 9d ed 42 5c dd b1 23 82 66 05 33 a8 ad 70 44 ae 4c 39 d5 89 a0 f3 dc 61 63 7a da 1e 34 ff ab a9 68 eb 9b 3e 18 a2 4c cc e7 86 97 56 59 66 8c c2 ec 77 6e 4a 32 29 ee e5 24 ef d6 f9 1c bb bf d0 29 f2 3d 70 6a b2 aa dc 32 a8 bd 36 dd 28 91 5f 5b d6 d7 08 d1 83 10 50 21 02 ef 6b fe 8d e3 71 c5 34 2d 75 d3 26 7b 5d 60 1e 03 6c 11 02 81 81 01 17 91 c8 15 2e 28 b3 af a6 d3 10 43 a0 e1 f6 57 2a 38 fd a3 df 80 e1 e8 8a ec d0 02 86 52 ab f3 e4 53 b2 d5 d8 9c d1 14 78 7b 2e 19 08 d3 fc c3 98 ed e1 53 04 a2 dd 5b bd ad 3f 93 0f b8 0b a7 bb 0f d3 f3 0e 6b 88 d1 4b 4f 0e 7e 28 03 36 de a8 2b 2a 29 c8 91 cc 75 16 29 f1 7f 57 63 74 9b dc 1f 10 29 4d e5 d7 f0 07 81 d0 70 45 e8 9d 15 de e1 c