 [00 00 00 02])), concat(sha256(concat(h, [00 00 00 03])), concat(sha256(concat(h, [00 00 00 04])), concat(sha256(concat(h, [00 00 00 05])), sha256(concat(h, [00 00 00 06])))))))).slice(0, 223); return sig.length === 257 && m.slice(0, 1) === [00] && em.slice(255, 256) === [bc] && h === sha256(concat(zeros(8), concat(sha256(msg), salt))) && xor(em.slice(0, 223), mask) === concat(zeros(222 - salt.length), concat([01], salt)); }

